"""matplotlib.collections — collection stubs."""

import sys as _sys
import numpy as _np


# Single shared no-op so unknown methods don't crash. Logs once per
# (class, method-name) pair so missing-method gaps surface in stderr
# but user scripts keep running.
_collection_warned = set()

def _collection_getattr_fallback(self, name):
    """Class-level __getattr__ used by Collection (and inherited by all
    subclasses). Only fires when normal lookup fails — explicit methods
    on the class always win."""
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _collection_warned:
        _collection_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] collections.{key}() not implemented — "
                f"returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Collection:
    __getattr__ = _collection_getattr_fallback
    def __init__(self, **kwargs):
        self._facecolors = kwargs.get('facecolors', [])
        self._edgecolors = kwargs.get('edgecolors', [])
        self._linewidths = kwargs.get('linewidths', [1.0])
        self._alpha = kwargs.get('alpha', None)
        self._label = kwargs.get('label', '')
        self._visible = True
    def set_alpha(self, a): self._alpha = a
    def get_alpha(self): return self._alpha
    def set_facecolor(self, c): self._facecolors = c
    def set_edgecolor(self, c): self._edgecolors = c
    def set_facecolors(self, c): self._facecolors = c
    def set_edgecolors(self, c): self._edgecolors = c
    def get_facecolor(self): return self._facecolors
    def get_edgecolor(self): return self._edgecolors
    def get_facecolors(self): return self._facecolors
    def get_edgecolors(self): return self._edgecolors
    def set_array(self, A): self._A = A
    def get_array(self): return getattr(self, '_A', None)
    def set_clim(self, vmin=None, vmax=None):
        self._clim = (vmin, vmax)
    def get_clim(self): return getattr(self, '_clim', (None, None))
    def set_norm(self, n): self._norm = n
    def get_norm(self): return getattr(self, '_norm', None)
    def set_cmap(self, cmap): self._cmap = cmap
    def get_cmap(self): return getattr(self, '_cmap', None)
    def set_visible(self, v): self._visible = bool(v)
    def get_visible(self): return self._visible
    def set_label(self, s): self._label = str(s) if s is not None else ''
    def get_label(self): return self._label
    def remove(self): pass
    def autoscale(self): pass
    def autoscale_None(self): pass
    def changed(self): pass


class PathCollection(Collection):
    """Scatter plot collection."""
    def __init__(self, paths=None, **kwargs):
        super().__init__(**kwargs)
        self._paths = paths
        self._offsets = kwargs.get('offsets', _np.empty((0, 2)))
        self._sizes = kwargs.get('sizes', [20])

    def get_offsets(self): return self._offsets
    def set_offsets(self, offsets): self._offsets = offsets
    def get_sizes(self): return self._sizes
    def set_sizes(self, sizes): self._sizes = sizes

    def legend_elements(self, prop='colors', num='auto', fmt=None, func=None,
                         **kwargs):
        """Return ``(handles, labels)`` suitable for
        ``ax.legend(*pc.legend_elements())``.

        Builds one Line2D proxy per unique value found in either the
        scalar array (``_A``), the facecolors, or the sizes — depending
        on ``prop``. Mirrors upstream's behaviour.
        """
        from matplotlib.lines import Line2D
        # Choose source values based on ``prop``.
        if prop == 'sizes':
            values = _np.asarray(self._sizes)
        elif prop == 'colors':
            A = getattr(self, '_A', None)
            if A is not None and len(A) > 0:
                values = _np.asarray(A)
            else:
                values = _np.asarray(self._facecolors)
        else:
            values = _np.asarray(getattr(self, '_A', self._facecolors))
        if values is None or len(values) == 0:
            return [], []
        # Pick representative values to legend.
        if values.ndim == 2:
            # Color rows — dedupe.
            uniq = _np.unique(values, axis=0)
        else:
            uniq = _np.unique(values)
            if num != 'auto' and isinstance(num, int) and len(uniq) > num:
                # Sub-sample to ``num`` values uniformly.
                idx = _np.linspace(0, len(uniq) - 1, num).astype(int)
                uniq = uniq[idx]
        # Resolve a colour for each representative value.
        cmap = getattr(self, '_cmap', None)
        if isinstance(cmap, str):
            try:
                from matplotlib.cm import get_cmap
                cmap = get_cmap(cmap)
            except Exception:
                cmap = None
        norm = getattr(self, '_norm', None)
        if norm is None and values.ndim == 1:
            from matplotlib.colors import Normalize
            norm = Normalize(vmin=float(uniq.min()), vmax=float(uniq.max()))
        handles, labels = [], []
        for i, v in enumerate(uniq):
            if values.ndim == 2:
                col = tuple(float(c) for c in v[:4])
            elif cmap is not None and norm is not None:
                col = tuple(float(c) for c in cmap(norm(float(v))))
            else:
                col = (0.3, 0.5, 0.8, 1.0)
            h = Line2D([0], [0], marker='o', linestyle='',
                       markerfacecolor=col, markeredgecolor=col,
                       markersize=8, color=col)
            handles.append(h)
            # Resolve label text.
            if fmt is not None:
                try: lbl = fmt % v
                except Exception: lbl = str(v)
            elif func is not None:
                try: lbl = str(func(v))
                except Exception: lbl = str(v)
            else:
                lbl = str(v if not hasattr(v, 'tolist') else v.tolist())
            labels.append(lbl)
        return handles, labels


class LineCollection(Collection):
    def __init__(self, segments=None, **kwargs):
        super().__init__(**kwargs)
        self._segments = segments

    def set_segments(self, segments): self._segments = segments
    def get_segments(self): return self._segments


class PolyCollection(Collection):
    def __init__(self, verts=None, **kwargs):
        super().__init__(**kwargs)
        self._verts = verts


class QuadMesh(Collection):
    pass


class PatchCollection(Collection):
    def __init__(self, patches=None, **kwargs):
        super().__init__(**kwargs)
        self._patches = patches or []


class EventCollection(Collection):
    def __init__(self, positions=None, **kwargs):
        super().__init__(**kwargs)
        self._positions = positions


class EllipseCollection(Collection):
    pass


class TriMesh(Collection):
    pass


# ─── Added: missing public Collection classes from upstream ────


class RegularPolyCollection(Collection):
    """Collection of identical regular polygons (squares, pentagons, etc.)
    positioned at ``offsets`` with shared rotation and size. Used by
    :func:`matplotlib.pyplot.scatter` when a marker is a regular n-gon.
    """

    def __init__(self, numsides=4, *, rotation=0, sizes=(1,), offsets=None,
                 **kwargs):
        super().__init__(**kwargs)
        self.numsides = int(numsides)
        self.rotation = float(rotation)
        self._sizes = list(sizes)
        self._offsets = offsets if offsets is not None else _np.empty((0, 2))

    def get_numsides(self):    return self.numsides
    def get_rotation(self):    return self.rotation
    def get_sizes(self):       return self._sizes
    def set_sizes(self, s):    self._sizes = list(s)
    def get_offsets(self):     return self._offsets
    def set_offsets(self, o):  self._offsets = o


class StarPolygonCollection(RegularPolyCollection):
    """Five-pointed (by default) star markers, expressed as a regular
    polygon collection with ``numsides=5`` and an odd skip pattern."""

    def __init__(self, numsides=5, *, rotation=0, sizes=(1,), **kwargs):
        super().__init__(numsides=numsides, rotation=rotation,
                         sizes=sizes, **kwargs)


class AsteriskPolygonCollection(RegularPolyCollection):
    """Asterisk markers — drawn as a degenerate regular polygon where
    every edge passes through the centre."""

    def __init__(self, numsides=5, *, rotation=0, sizes=(1,), **kwargs):
        super().__init__(numsides=numsides, rotation=rotation,
                         sizes=sizes, **kwargs)


class CircleCollection(Collection):
    """Circles at ``offsets`` with per-marker radii in ``sizes`` (areas)."""

    def __init__(self, sizes=(1,), *, offsets=None, **kwargs):
        super().__init__(**kwargs)
        self._sizes = list(sizes)
        self._offsets = offsets if offsets is not None else _np.empty((0, 2))

    def get_sizes(self):       return self._sizes
    def set_sizes(self, s):    self._sizes = list(s)
    def get_offsets(self):     return self._offsets
    def set_offsets(self, o):  self._offsets = o


class PolyQuadMesh(QuadMesh):
    """:class:`QuadMesh` rendered as polygons rather than as an image —
    useful when individual cells need to be hatched or have different
    edge styles. We inherit the QuadMesh facade unchanged.
    """

    def __init__(self, coordinates=None, **kwargs):
        super().__init__(**kwargs)
        # coordinates is an (M+1, N+1, 2) array describing quad corners.
        self._coordinates = coordinates


class FillBetweenPolyCollection(PolyCollection):
    """Polygon collection produced by :func:`fill_between` /
    :func:`fill_betweenx`. Holds the two original boundary arrays so
    they can be queried back from the artist.
    """

    def __init__(self, t, f1, f2, *, where=None, orientation='vertical',
                 **kwargs):
        # Build a single closed-polygon vertex list from the two curves.
        t = _np.asarray(t, dtype=float)
        f1 = _np.asarray(f1, dtype=float)
        f2 = _np.asarray(f2, dtype=float)
        if orientation == 'vertical':
            verts = list(zip(t, f1)) + list(zip(t[::-1], f2[::-1]))
        else:
            verts = list(zip(f1, t)) + list(zip(f2[::-1], t[::-1]))
        super().__init__(verts=[verts], **kwargs)
        self._t = t
        self._f1 = f1
        self._f2 = f2
        self._where = where
        self._orientation = orientation

    def get_paths(self):
        return [self._verts] if self._verts else []


