def _attach_collection_methods(cls):
    def contains(self, mouseevent):   return False, {}
    def draw(self, renderer):          pass
    def get_antialiased(self):         return getattr(self, '_aa', True)
    def set_antialiased(self, b):      self._aa = b
    def get_capstyle(self):            return getattr(self, '_capstyle', 'butt')
    def set_capstyle(self, s):         self._capstyle = s
    def get_joinstyle(self):           return getattr(self, '_joinstyle', 'miter')
    def set_joinstyle(self, s):        self._joinstyle = s
    def get_linestyle(self):           return getattr(self, '_linestyles', ['-'])
    def set_linestyle(self, s):        self._linestyles = [s] if isinstance(s, str) else list(s)
    def get_linestyles(self):          return self.get_linestyle()
    def set_linestyles(self, s):       self.set_linestyle(s)
    def get_linewidth(self):           return self._linewidths
    def set_linewidth(self, w):
        self._linewidths = [w] if not hasattr(w, '__iter__') else list(w)
    def get_linewidths(self):          return self.get_linewidth()
    def set_linewidths(self, w):       self.set_linewidth(w)
    def get_hatch(self):               return getattr(self, '_hatch', None)
    def set_hatch(self, h):            self._hatch = h
    def get_fill(self):                return getattr(self, '_fill', True)
    def set_fill(self, b):             self._fill = b
    def get_paths(self):               return getattr(self, '_paths', [])
    def get_offsets(self):             return getattr(self, '_offsets', [])
    def set_offsets(self, offsets):    self._offsets = offsets
    def get_offset_transform(self):    return None
    def set_offset_transform(self, t): self._offset_transform = t
    def get_transforms(self):          return []
    def get_transform(self):           return None
    def get_datalim(self, transData):
        import numpy as _np
        return _np.array([0.0, 0.0, 1.0, 1.0])
    def get_pickradius(self):          return getattr(self, '_pickradius', 5)
    def set_pickradius(self, r):       self._pickradius = float(r)
    def get_urls(self):                return getattr(self, '_urls', [])
    def set_urls(self, urls):          self._urls = list(urls) if urls else []
    def get_window_extent(self, renderer=None): return None
    def get_zorder(self):              return getattr(self, '_zorder', 1)
    def set_zorder(self, z):           self._zorder = z

    def set_color(self, c):
        self._facecolors = c; self._edgecolors = c
    def set_colors(self, c):
        self.set_color(c)
    def get_color(self):
        return self._facecolors
    def get_colors(self):
        return [self._facecolors, self._edgecolors]
    def update_from(self, other):
        for attr in ('facecolor', 'edgecolor', 'linewidth', 'alpha'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass

    _l = locals()
    for n in ('contains', 'draw', 'get_antialiased', 'set_antialiased',
              'get_capstyle', 'set_capstyle', 'get_joinstyle', 'set_joinstyle',
              'get_linestyle', 'set_linestyle', 'get_linestyles', 'set_linestyles',
              'get_linewidth', 'set_linewidth', 'get_linewidths', 'set_linewidths',
              'get_hatch', 'set_hatch', 'get_fill', 'set_fill',
              'get_paths', 'get_offsets', 'set_offsets',
              'get_offset_transform', 'set_offset_transform',
              'get_transforms', 'get_transform', 'get_datalim',
              'get_pickradius', 'set_pickradius',
              'get_urls', 'set_urls', 'get_window_extent',
              'get_zorder', 'set_zorder',
              'set_color', 'set_colors', 'get_color', 'get_colors',
              'update_from'):
        if n in _l:
            setattr(cls, n, _l[n])


_attach_collection_methods(Collection)


