# ─── Added: more Collection helpers ─────────────────────────────────


def _coll_set_paths(self, paths):
    self._paths = paths


def _coll_update_scalarmappable(self):
    """Recompute facecolors from the attached scalar array by running
    each value through (norm → cmap). Mirrors upstream's behaviour."""
    A = getattr(self, '_A', None)
    if A is None:
        return
    cmap = getattr(self, '_cmap', None)
    # Resolve string cmap names to the actual Colormap object.
    if isinstance(cmap, str):
        try:
            from matplotlib.cm import get_cmap
            cmap = get_cmap(cmap)
        except Exception:
            cmap = None
    if cmap is None:
        try:
            from matplotlib.cm import get_cmap
            cmap = get_cmap('viridis')
        except Exception:
            return
    self._cmap = cmap
    norm = getattr(self, '_norm', None)
    if norm is None:
        try:
            from matplotlib.colors import Normalize
            vmin, vmax = getattr(self, '_clim', (None, None))
            if vmin is None: vmin = float(_np.nanmin(A))
            if vmax is None: vmax = float(_np.nanmax(A))
            norm = Normalize(vmin=vmin, vmax=vmax)
            self._norm = norm
        except Exception:
            return
    try:
        normalized = norm(_np.asarray(A, dtype=float))
        colors = cmap(normalized)
        self._facecolors = colors
    except Exception:
        pass


def _coll_get_datalim(self, transData):
    """Return a Bbox bounding all offsets. Works for any collection that
    set ``_offsets`` (scatter, line, poly, …)."""
    from matplotlib.transforms import Bbox
    offsets = getattr(self, '_offsets', None)
    if offsets is None or (hasattr(offsets, 'size') and offsets.size == 0):
        return Bbox.from_extents(0, 0, 1, 1)
    arr = _np.asarray(offsets, dtype=float)
    if arr.ndim != 2 or arr.shape[0] == 0:
        return Bbox.from_extents(0, 0, 1, 1)
    x_min, y_min = float(arr[:, 0].min()), float(arr[:, 1].min())
    x_max, y_max = float(arr[:, 0].max()), float(arr[:, 1].max())
    return Bbox.from_extents(x_min, y_min, x_max, y_max)


Collection.set_paths             = _coll_set_paths
Collection.update_scalarmappable = _coll_update_scalarmappable
Collection.get_datalim           = _coll_get_datalim


# ─── Added: EventCollection methods ─────────────────────────────────


def _ec_add_positions(self, position):
    if self._positions is None: self._positions = []
    self._positions = list(self._positions) + [position]
def _ec_append_positions(self, position):
    if self._positions is None: self._positions = []
    self._positions = list(self._positions) + list(position)
def _ec_extend_positions(self, position):
    if self._positions is None: self._positions = []
    self._positions = list(self._positions) + list(position)
def _ec_get_linelength(self):         return getattr(self, '_linelength', 1)
def _ec_set_linelength(self, l):      self._linelength = float(l)
def _ec_get_lineoffset(self):         return getattr(self, '_lineoffset', 0)
def _ec_set_lineoffset(self, o):      self._lineoffset = float(o)
def _ec_get_orientation(self):        return getattr(self, '_orientation', 'horizontal')
def _ec_set_orientation(self, o):     self._orientation = o
def _ec_get_positions(self):          return self._positions
def _ec_set_positions(self, p):       self._positions = p
def _ec_is_horizontal(self):          return self._orientation == 'horizontal'
def _ec_switch_orientation(self):
    self._orientation = 'vertical' if self._orientation == 'horizontal' else 'horizontal'

for n in ('add_positions', 'append_positions', 'extend_positions',
          'get_linelength', 'set_linelength', 'get_lineoffset',
          'set_lineoffset', 'get_orientation', 'set_orientation',
          'get_positions', 'set_positions', 'is_horizontal',
          'switch_orientation'):
    setattr(EventCollection, n, locals()[f'_ec_{n}'])


